function compareKeys(a, b) {
  const x = [].concat(a);
  const y = [].concat(b);
  for (let i = 0; i < x.length; i++) {
    if (x[i] < y[i]) return -1;
    if (x[i] > y[i]) return 1;
  }
  return 0;
