const assert = require('node:assert');
const { feedPage } = require('../src/feed');

const events = [{ id: 'a', createdAt: 1 }, { id: 'b', createdAt: 3 }, { id: 'c', createdAt: 2 }];

test('pages newest first', () => {
  const first = feedPage(events, { limit: 2 });
  assert.deepStrictEqual(first.items.map((e) => e.id), ['b', 'c']);
  const second = feedPage(events, { after: first.next, limit: 2 });
  assert.deepStrictEqual(second.items.map((e) => e.id), ['a']);
  assert.strictEqual(second.next, null);
});
